<script>
// 图片选择函数
function selectImage(inputId) {
    const input = document.createElement(\'input\');
    input.type = \'file\';
    input.accept = \'image/*\';
    input.style.display = \'none\';
    
    input.onchange = function(e) {
        const file = e.target.files[0];
        if (!file) return;
        
        // 验证文件类型
        if (!file.type.match(/^image\\/(jpeg|jpg|png|gif|webp|ico)$/)) {
            alert(\'请选择图片文件（jpg、png、gif、webp、ico）\');
            return;
        }
        
        // 验证文件大小（最大 5MB）
        if (file.size > 5 * 1024 * 1024) {
            alert(\'图片大小不能超过 5MB\');
            return;
        }
        
        // 创建 FormData
        const formData = new FormData();
        formData.append(\'file\', file);
        formData.append(\'module\', \'setting\'); // 添加模块标识
        
        // 获取 CSRF Token
        const csrfToken = document.getElementById(\'csrf_token\')?.value || \'\';
        formData.append(\'csrf_token\', csrfToken);
        
        // 显示上传中提示
        const targetInput = document.getElementById(inputId);
        if (!targetInput) {
            alert(\'未找到目标输入框: \' + inputId);
            return;
        }
        const originalValue = targetInput.value;
        targetInput.value = \'上传中...\';
        targetInput.disabled = true;
        
        // 上传文件
        fetch(\'/admin/upload/do\', {
            method: \'POST\',
            body: formData
        })
        .then(response => response.json())
        .then(data => {
            targetInput.disabled = false;
            if (data.errno === 0 && data.data && data.data.length > 0) {
                // 上传成功，设置图片URL
                targetInput.value = data.data[0];
                // 显示预览
                const previewId = \'preview_\' + inputId.replace(\'setting_\', \'\');
                const preview = document.getElementById(previewId);
                if (preview) {
                    preview.innerHTML = \'<img src="\' + data.data[0] + \'" width="200" class="img-thumbnail">\';
                }
            } else {
                // 上传失败
                targetInput.value = originalValue;
                alert(data.message || \'上传失败\');
            }
        })
        .catch(error => {
            targetInput.disabled = false;
            targetInput.value = originalValue;
            console.error(\'上传错误:\', error);
            alert(\'上传失败，请重试\');
        });
    };
    
    // 触发文件选择
    document.body.appendChild(input);
    input.click();
    document.body.removeChild(input);
}

// 表单提交处理
document.getElementById(\'settingForm\')?.addEventListener(\'submit\', function(e) {
    e.preventDefault();
    
    const form = this;
    const button = form.querySelector(\'button[type="submit"]\');
    const originalText = button.innerHTML;
    
    // 禁用提交按钮，防止重复提交
    button.disabled = true;
    button.innerHTML = \'<i class="fas fa-spinner fa-spin"></i> 保存中...\';
    
    // 使用Fetch API提交表单
    fetch(form.action, {
        method: \'POST\',
        body: new FormData(form),
        headers: {
            \'X-Requested-With\': \'XMLHttpRequest\'
        }
    })
    .then(response => response.json())
    .then(data => {
        if (data.code === 0) {
            // 保存成功，显示提示并跳转
            if (data.message) {
                alert(data.message);
            }
            // 跳转到指定URL或刷新页面
            window.location.href = data.url || \'/admin/setting\';
        } else {
            // 保存失败，显示错误信息
            alert(data.message || \'保存失败\');
            // 恢复提交按钮
            button.disabled = false;
            button.innerHTML = originalText;
        }
    })
    .catch(error => {
        console.error(\'保存失败:\', error);
        alert(\'保存失败，请重试\');
        // 恢复提交按钮
        button.disabled = false;
        button.innerHTML = originalText;
    });
});
</script>

